import net.minecraft.util.math.BlockPos;
/** Actual typed native state patch, separate from split ownership/publication acceptance. */
public final class ArmCouplerReleasePatchChecks {
 private static int checks;private static void need(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 private static VehicleStructure.Cell cell(BlockCoupler block,BlockPos pos,EnumFacing face,boolean marked){NBTTagCompound n=new NBTTagCompound();n.setString("id","vandorlabs:square_coupler");n.setBoolean("CouplerRequested",true);n.setUniqueId("CouplerControlIdentity",new UUID(7,pos.getX()+1));n.setString("FutureField","retained");NBTTagCompound caps=new NBTTagCompound();caps.setString("physical","opaque");n.setTag("ForgeCaps",caps);if(marked)n.setBoolean("VehicleArmCouplerReleased",true);return new VehicleStructure.Cell(pos,block.getDefaultState().withProperty(BlockCoupler.FACING,face).withProperty(BlockCoupler.LOCKED,true),n);}
 public static void main(String[] args){net.minecraft.init.Bootstrap.register();net.minecraftforge.fml.common.registry.GameRegistry.registerTileEntity(TileCoupler.class,new net.minecraft.util.ResourceLocation("vandorlabs:square_coupler"));BlockCoupler block=new BlockCoupler();BlockPos a=BlockPos.ORIGIN,b=a.east(),other=a.east(5);VehicleStructure.Cell first=cell(block,a,EnumFacing.EAST,true),second=cell(block,b,EnumFacing.WEST,true),unrelated=cell(block,other,EnumFacing.EAST,true);VehicleStructure source=VehicleStructure.display(Arrays.asList(first,unrelated));List<VehicleStructure.Cell> cells=new ArrayList<>(Arrays.asList(first,second,unrelated));VehicleCouplingPlan.clearRejoinedProof(cells,source,a,Collections.singleton(b));for(int i=0;i<2;i++){NBTTagCompound expected=(i==0?first:second).tileData();expected.removeTag("VehicleArmCouplerReleased");need(cells.get(i).tileData().equals(expected),"only selected pair proof cleared");}need(cells.get(2)==unrelated&&unrelated.tileBoolean("VehicleArmCouplerReleased"),"unrelated marked physical owner unchanged");need(first.tileBoolean("VehicleArmCouplerReleased")&&second.tileBoolean("VehicleArmCouplerReleased"),"original immutable snapshots untouched");List<VehicleStructure.Cell> bad=new ArrayList<>(Arrays.asList(first,second,unrelated));boolean refused=false;try{VehicleCouplingPlan.clearRejoinedProof(bad,source,a,Collections.emptySet());}catch(IllegalArgumentException expected){refused=true;}need(refused&&bad.get(0)==first&&bad.get(1)==second,"invalid ownership admission refuses before either patch");bad=new ArrayList<>(Arrays.asList(first,cell(block,b,EnumFacing.NORTH,true),unrelated));refused=false;try{VehicleCouplingPlan.clearRejoinedProof(bad,source,a,Collections.singleton(b));}catch(IllegalArgumentException expected){refused=true;}need(refused&&bad.get(0)==first,"nonopposing pair cannot clear proof");UUID owner=new UUID(31,32),generation=new UUID(33,34);NBTTagCompound prior=CouplerAssociationData.chosenPatch(first.tileData(),owner,new UUID(35,36),CouplerAssociation.Boundary.NEW_HEAD_INSTALLATION,true,false);VehicleStructure.Cell unpaired=new VehicleStructure.Cell(a,first.state,prior);VehicleStructure scopedSource=VehicleStructure.display(Arrays.asList(unpaired,unrelated));List<VehicleStructure.Cell> joined=new ArrayList<>(Arrays.asList(unpaired,second,unrelated));boolean missingScope=false;try{VehicleCouplingPlan.clearRejoinedProof(joined,scopedSource,a,Collections.singleton(b));}catch(IllegalArgumentException expected){missingScope=true;}need(missingScope&&joined.get(0)==unpaired,"legacy attach entry cannot retain stale unpaired proof");VehicleCouplingPlan.clearRejoinedProof(joined,scopedSource,a,Collections.singleton(b),owner,generation);for(int i=0;i<2;i++){NBTTagCompound data=joined.get(i).tileData();CouplerAssociation proof=CouplerAssociationData.read(data);need(proof.state==CouplerAssociation.EXPECTED_PAIR&&proof.vehicle.equals(owner)&&proof.generation.equals(generation),"genuine attach replaces unpaired with scoped expected-pair on both heads");need(!data.hasKey("VehicleArmCouplerReleased")&&data.getCompoundTag("ForgeCaps").equals(first.tileData().getCompoundTag("ForgeCaps"))&&data.getString("FutureField").equals("retained"),"attach preserves opaque data and clears only actual released proof");}need(joined.get(2)==unrelated&&unpaired.tileData().equals(prior),"unrelated and beforeimage immutable");NBTTagCompound malformed=second.tileData();malformed.setString(CouplerAssociationData.KEY,"unsupported");VehicleStructure.Cell broken=new VehicleStructure.Cell(b,second.state,malformed);List<VehicleStructure.Cell> atomic=new ArrayList<>(Arrays.asList(unpaired,broken));refused=false;try{VehicleCouplingPlan.clearRejoinedProof(atomic,scopedSource,a,Collections.singleton(b),owner,generation);}catch(IllegalArgumentException expected){refused=true;}need(refused&&atomic.get(0)==unpaired&&atomic.get(1)==broken,"second-head decode refusal leaves both chosen patches unapplied");
 System.out.println("Arm Coupler release patch PASS checks="+checks+" exact pair-only proof/caps/identity/original preservation; no transfer claim");}
}
